    "2c248c19-735a-4de5-8748-42090b4c9ab3": "a3000000-0000-0000-0000-000000000005",
    "6609159c-67fd-4a4d-ad56-808aa77d3e68": "a3000000-0000-0000-0000-000000000006",
    "e0ef9b4c-920e-40e1-badc-40c0739effe1": "a3000000-0000-0000-0000-000000000007",
    "51e480f6-b93e-4f2e-92db-da3d97524087": "a3000000-0000-0000-0000-000000000008",
    "ca18984b-61cc-46a3-8f6b-7ab983d0bf42": "a3000000-0000-0000-0000-000000000009",
    "b40050a4-13a0-4bbe-a0fb-b7c957c5e99d": "a3000000-0000-0000-0000-000000000009",
    "86a3eb50-89a8-4498-a58e-66ab1f49f052": "a3000000-0000-0000-0000-000000000010"
  }';
  t record;
  v_allowed text;
  v_has_data boolean;
  v_tables text[] := '{}';
begin
  -- パーティションの親は行を持たないため、行を持つ表を1つずつonlyで調べる。
  for t in
    select schema_name, table_name from pg_temp.restore_tables
    where check_empty and relkind = 'r'
    order by schema_name, table_name
  loop
    -- 許容する行の条件。条件が真でない行が1つでもあれば、空でない。
    -- 匿名化先の認証の行は、固定IDに加えて、他の列(メール、電話、パスワード、トークン、メタデータなど)に値が無いことも確かめる。
    v_allowed := case t.schema_name || '.' || t.table_name
      when 'auth.users' then $allowed$
        r.id = $1
        and r.instance_id = '00000000-0000-0000-0000-000000000000'
        and r.aud = 'authenticated'
        and r.role = 'authenticated'
        and r.banned_until = 'infinity'
        and not exists (
          select 1
          from jsonb_each(to_jsonb(r) - array['instance_id', 'id', 'aud', 'role', 'banned_until', 'created_at', 'updated_at']) as c
          where c.value not in ('null', '""', 'false', '0', '{}')
        )
      $allowed$
      when 'public.users' then 'r.id = $1 and r.name is null'
      when 'public.target_faces' then 'r.id = any ($2)'
      when 'public.target_face_spots' then 'r.id = any ($3)'
      when 'public.target_face_rings' then 'r.id = any ($4)'
      when 'public.preset_rounds' then 'r.id = any ($5) and r.owner_id is null'
      when 'public.preset_distances' then $allowed$
        $6 ->> r.id::text = r.preset_id::text
        and exists (select 1 from public.preset_rounds p where p.id = r.preset_id and p.owner_id is null)
      $allowed$
      else 'false'
    end;
    begin
      execute format('select exists (select 1 from only %I.%I as r where (%s) is not true)', t.schema_name, t.table_name, v_allowed)
      into v_has_data
      using c_deleted_user, c_target_face_ids, c_target_face_spot_ids, c_target_face_ring_ids, c_preset_round_ids, c_preset_distance_parents;
    exception when others then
      -- 構造と権限のエラー(SQLSTATEの42)の本文は表や列の名前だけを含む。他の本文は、行の内容を含み得るため表示しない。
      raise exception '確認できない構造・権限: %.% を調べられません(SQLSTATE %: %)', t.schema_name, t.table_name, sqlstate,
        case when sqlstate like '42%' then sqlerrm else '本文は表示しません' end;
    end;
    if v_has_data then
      v_tables := v_tables || format('%s.%s', t.schema_name, t.table_name);
    end if;
  end loop;
  if cardinality(v_tables) > 0 then
    raise exception '空でない表があります: %。利用者や記録のあるDBへは復元できません', array_to_string(v_tables, ', ');
  end if;
end;
$$;
